create or replace function public.resolve_registry_relationship_endpoint_from_alias(p_relationship_id uuid,p_endpoint_side text,p_reason text) returns public.registry_entity_relationships language plpgsql security definer set search_path=public,auth as $$ declare v_relationship public.registry_entity_relationships; v_slug text; v_candidate_id uuid; v_match_count integer; v_result public.registry_entity_relationships; begin if not (auth.role()='service_role' or public.current_user_has_capability('manage_registry') or public.current_user_has_capability('manage_review_queue') or public.current_user_is_administrator()) then raise exception 'You do not have permission to resolve Registry relationship endpoints.'; end if; if p_endpoint_side not in ('source','target') then raise exception 'Endpoint side must be source or target.'; end if; if nullif(btrim(p_reason),'') is null then raise exception 'A resolution reason is required.'; end if; select * into v_relationship from public.registry_entity_relationships where id=p_relationship_id for update; if not found then raise exception 'Registry relationship not found.'; end if; v_slug:=case when p_endpoint_side='source' then v_relationship.source_slug else v_relationship.target_slug end; select count(*)::integer,min(a.canonical_artist_id::text)::uuid into v_match_count,v_candidate_id from public.registry_artist_aliases a where a.alias_slug=v_slug and coalesce(a.status,'active')<>'rejected'; if v_match_count=0 then raise exception 'No active canonical artist alias match was found.'; end if; if v_match_count>1 then raise exception 'The artist alias is ambiguous and requires manual review.'; end if; select public.resolve_registry_relationship_endpoint(p_relationship_id,p_endpoint_side,'artist',v_candidate_id,p_reason) into v_result; return v_result; end; $$; revoke all on function public.resolve_registry_relationship_endpoint_from_alias(uuid,text,text) from public,anon; grant execute on function public.resolve_registry_relationship_endpoint_from_alias(uuid,text,text) to authenticated,service_role;;
